INSERT INTO articles (slug,title,teaser,body,category,topic,region,kind,author,image,source_name,source_url,status,published_at,updated_at,meta_title,meta_description,focus_keyword,keywords,image_alt,image_prompt,faq,service) VALUES ('energiepreise-oesterreich-erzeugerpreise-september-2026-plus-6-prozent','Energiepreise in Österreich: Erzeugerpreise steigen um 6 Prozent','Energie war im September 11,4 Prozent teurer als vor einem Jahr, Gasversorgung sogar 13 Prozent. Der Erzeugerpreisindex stieg laut Statistik Austria um 6,0 Prozent.','Die **Energiepreise** treiben die Erzeugerpreise in Österreich weiter nach oben: Im September 2026 kostete Energie für die heimischen Produzenten um 11,4 Prozent mehr als ein Jahr zuvor. Das geht aus der am Freitag veröffentlichten Erzeugerpreisstatistik von Statistik Austria hervor. Insgesamt lag der Erzeugerpreisindex für den produzierenden Bereich um 6,0 Prozent über dem Vorjahreswert.

## Energiepreise legen seit Sommer deutlich zu

Der Gesamtindex erreichte im September 122,4 Punkte, gemessen am Basisjahr 2021. Damit hat sich der Aufwärtstrend der vergangenen Monate beschleunigt: Im Juli betrug die Jahresteuerung bei den Erzeugerpreisen noch 3,3 Prozent, im August 4,7 Prozent. Zu Jahresbeginn waren die Werte sogar negativ, im Jänner lag das Minus bei 1,5 Prozent.

Noch deutlicher ist die Entwicklung bei der Energie selbst. Der Preisauftrieb in diesem Bereich lag im Juli bei 2,6 Prozent und im August bei 7,3 Prozent, bevor er im September auf 11,4 Prozent kletterte. Laut Statistik Austria war die Energie gemeinsam mit den Vorleistungsgütern hauptverantwortlich für den Anstieg des Gesamtindex.

Im Vergleich zum Vormonat August stieg der Index insgesamt um 1,2 Prozent. Die Preise in der Energieversorgung erhöhten sich innerhalb eines Monats um 3,6 Prozent und damit stärker als in anderen Branchen.

## Gasversorgung um 13 Prozent teurer

Besonders kräftig fiel das Plus bei Gas aus. Industriell erzeugte Gase und Dienstleistungen der Gasversorgung waren im September um 13,0 Prozent teurer als im Vorjahresmonat. Auch Mineralölerzeugnisse verteuerten sich im Jahresabstand deutlich, eine genaue Rate nennt die Statistikbehörde dafür in ihrer Aussendung nicht.

Für Betriebe, deren Produktion viel Wärme oder Prozessenergie benötigt, bedeutet das steigende Kosten. Ob und wie stark diese an Kundinnen und Kunden weitergegeben werden, lässt sich aus den Erzeugerpreisen allein nicht ablesen. Der Index bildet die Ab-Werk-Preise ohne Mehrwertsteuer ab, die Hersteller beim Verkauf ihrer Produkte im In- und Ausland erzielen.

## Vorleistungsgüter: Metalle mit fast 50 Prozent Plus

Neben der Energie zogen auch die Preise für Vorleistungsgüter spürbar an. Sie lagen im September im Schnitt um 7,4 Prozent über dem Vorjahresniveau, nach 7,2 Prozent im August und 6,6 Prozent im Juli. Den stärksten Sprung verzeichneten Nichteisen-Metalle und Halbzeug mit einem Plus von 48,4 Prozent.

Weitere Teuerungen im Überblick:

- Chemische Grundstoffe, Düngemittel, Kunststoffe in Primärform und synthetischer Kautschuk: plus 15,5 Prozent
- Kunststoffwaren: plus 6,8 Prozent
- Roheisen, Stahl und Ferrolegierungen: plus 6,0 Prozent
- Investitionsgüter insgesamt: plus 1,4 Prozent
- Land- und forstwirtschaftliche Maschinen: plus 3,6 Prozent
- Teile und Zubehör für Kraftwagen: plus 3,5 Prozent

## Konsumgüter kaum teurer

Deutlich ruhiger verlief die Entwicklung bei den Konsumgütern. Hier stiegen die Erzeugerpreise im Jahresvergleich nur um 0,3 Prozent, gleich stark wie im August. Teurer wurden vor allem Möbel mit 2,6 Prozent sowie Back- und Teigwaren mit 2,3 Prozent. Billiger als vor einem Jahr waren hingegen Milch und Milchprodukte mit minus 6,1 Prozent sowie haltbar gemachtes Fleisch mit minus 4,7 Prozent. In beiden Fällen schwächte sich der Preisrückgang gegenüber dem Vormonat allerdings ab.

## Was der Erzeugerpreisindex misst

Der Erzeugerpreisindex erfasst monatlich die durchschnittliche Preisentwicklung in Bergbau, Warenherstellung sowie Energie- und Wasserversorgung. Berücksichtigt werden Produkte, die von Unternehmen in Österreich hergestellt und verkauft werden, nach Abzug von Rabatten, aber inklusive gesetzlicher Abgaben. Die Septemberwerte gelten als vorläufiges Ergebnis. Für das dritte Quartal 2026 weist Statistik Austria insgesamt ein Plus von 4,7 Prozent gegenüber dem Vorjahresquartal aus.','energie','Heizen',NULL,'news','Presseinfo Redaktion','/assets/img/artikel/energiepreise-oesterreich-erzeugerpreise-september-2026-plus-6-prozent.webp','Statistik Austria','https://www.statistik.at/fileadmin/announcement/2026/10/20261030EPISeptember2026.pdf','published','2026-10-30T14:50:00.000Z','2026-10-30T14:47:11.228Z','Energiepreise Österreich: Erzeugerpreise +6 % im September','Energiepreise in Österreich: Laut Statistik Austria kostete Energie im September 11,4 % mehr, Gas sogar 13 %. Alle Zahlen zu den Erzeugerpreisen.','Energiepreise','["Energiepreise","Erzeugerpreise","Energiepreise Österreich","Erzeugerpreisindex September 2026","Gaspreise Österreich","Statistik Austria Erzeugerpreise","Teuerung Energie 2026","Gasversorgung teurer"]','Gasleitungen einer Verteilerstation – Energiepreise in Österreich steigen','Industrial gas pressure regulating station with yellow pipes and valves in a rural Austrian landscape in autumn, misty hills and colorful trees in background, overcast soft light, photorealistic, no text, no logos, no readable signs','[{"q":"Wie stark sind die Energiepreise für Produzenten gestiegen?","a":"Laut Statistik Austria lagen die Energiepreise im September 2026 um 11,4 Prozent über dem Vorjahresmonat, Gasversorgung war um 13,0 Prozent teurer."},{"q":"Wie hoch ist der Erzeugerpreisindex im September 2026?","a":"Der Index lag bei 122,4 Punkten (Basis 2021) und damit um 6,0 Prozent über dem Wert von September 2025."},{"q":"Was misst der Erzeugerpreisindex?","a":"Er bildet die Ab-Werk-Preise ohne Mehrwertsteuer ab, die Hersteller in Österreich für ihre Produkte im In- und Ausland erzielen."}]',0) ON CONFLICT(slug) DO UPDATE SET title=excluded.title, teaser=excluded.teaser, body=excluded.body, category=excluded.category, topic=excluded.topic, region=excluded.region, kind=excluded.kind, author=excluded.author, source_name=excluded.source_name, source_url=excluded.source_url, status=excluded.status, published_at=excluded.published_at, updated_at=excluded.updated_at, meta_title=excluded.meta_title, meta_description=excluded.meta_description, focus_keyword=excluded.focus_keyword, keywords=excluded.keywords, image_alt=excluded.image_alt, image_prompt=excluded.image_prompt, faq=excluded.faq, service=excluded.service, image=COALESCE(excluded.image, articles.image);
